import React from 'react';
import { format } from 'date-fns';
import { Container, Dot } from './Day.styles';
import { DayProps } from './Day.types';

const Day = ({ date, theme, activeModifiers }: DayProps): JSX.Element => {
  const dayNotSelected = activeModifiers?.selected !== true;
  return (
    <Container {...(dayNotSelected ? { theme } : {})}>
      {format(date, 'd')}
      {theme && dayNotSelected && <Dot className="dotMarker" theme={theme} />}
    </Container>
  );
};

export default Day;
